// Döviz kuru ekranı: USD/TRY ve EUR/TRY kurunu internetten çek, OLED'de güncelleme saatiyle göster.
// Kaynak: open.er-api.com (ücretsiz, anahtar istemez; kurlar günde bir yenilenir).
#include <WiFi.h>
#include <HTTPClient.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

const char* AG_ADI = "EvimWiFi";     // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";    // kendi Wi-Fi parolan
const char* ADRES = "https://open.er-api.com/v6/latest/USD";  // 1 USD kaç birim eder
const long SAAT_DILIMI = 3 * 3600;                // Türkiye: UTC+3
const unsigned long GUNCELLEME_MS = 30UL * 60000; // yarım saatte bir sor
const unsigned long HATA_BEKLEME_MS = 60000;      // olmazsa 1 dakika sonra tekrar dene

Adafruit_SSD1306 ekran(128, 64, &Wire, -1);
float usdTry = NAN;
float eurTry = NAN;
char guncelSaat[6] = "--:--";
unsigned long sonDeneme = 0;
bool ilkKez = true;
bool sonDenemeBasarili = false;

// JSON içinde "ANAHTAR": sayısını basit metin aramasıyla bulur. Yoksa NAN döner.
float sayiBul(const String& json, const char* anahtar, int bas) {
  String aranan = String("\"") + anahtar + "\":";
  int i = json.indexOf(aranan, bas);
  if (i < 0) return NAN;
  return json.substring(i + aranan.length()).toFloat();
}

bool kurlariAl() {
  HTTPClient http;
  http.begin(ADRES);
  int kod = http.GET();
  bool tamam = false;
  if (kod == 200) {
    String json = http.getString();
    int oranlar = json.indexOf("\"rates\"");
    if (oranlar >= 0) {
      float tl = sayiBul(json, "TRY", oranlar);   // 1 USD = tl TRY
      float euro = sayiBul(json, "EUR", oranlar); // 1 USD = euro EUR
      if (!isnan(tl) && !isnan(euro) && euro > 0) {
        usdTry = tl;
        eurTry = tl / euro;                       // 1 EUR = tl / euro TRY
        tamam = true;
      }
    }
  } else {
    Serial.printf("HTTP hatasi: %d\n", kod);
  }
  http.end();
  return tamam;
}

void ekranCiz() {
  ekran.clearDisplay();
  ekran.setTextSize(1);
  ekran.setCursor(0, 0);
  ekran.println("USD/TRY");
  ekran.setTextSize(2);
  ekran.setCursor(0, 10);
  if (isnan(usdTry)) ekran.println("--");
  else ekran.println(usdTry, 2);

  ekran.setTextSize(1);
  ekran.setCursor(0, 30);
  ekran.println("EUR/TRY");
  ekran.setTextSize(2);
  ekran.setCursor(0, 40);
  if (isnan(eurTry)) ekran.println("--");
  else ekran.println(eurTry, 2);

  ekran.setTextSize(1);
  ekran.setCursor(0, 56);
  ekran.printf("Guncel: %s", guncelSaat);
  ekran.display();
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);
  ekran.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  ekran.setTextColor(SSD1306_WHITE);
  ekran.clearDisplay();
  ekran.setCursor(0, 0);
  ekran.println("Wi-Fi baglaniyor...");
  ekran.display();

  WiFi.begin(AG_ADI, PAROLA);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("IP: ");
  Serial.println(WiFi.localIP());
  configTime(SAAT_DILIMI, 0, "pool.ntp.org");
}

void loop() {
  unsigned long bekleme = sonDenemeBasarili ? GUNCELLEME_MS : HATA_BEKLEME_MS;
  if (ilkKez || millis() - sonDeneme > bekleme) {
    ilkKez = false;
    sonDeneme = millis();
    sonDenemeBasarili = kurlariAl();
    if (sonDenemeBasarili) {
      struct tm saat;
      if (getLocalTime(&saat)) snprintf(guncelSaat, sizeof guncelSaat, "%02d:%02d", saat.tm_hour, saat.tm_min);
      Serial.printf("USD/TRY: %.2f  EUR/TRY: %.2f  (%s)\n", usdTry, eurTry, guncelSaat);
    } else {
      Serial.println("Kur alinamadi; 1 dakika sonra tekrar.");
    }
    ekranCiz();
  }
  delay(1000);
}
